export class AppComponent {
  readonly tabs: UrlTab[] = [
    { id: "overview", label: "Overview", component: OverviewPanelComponent },
    { id: "activity", label: "Activity", component: ActivityPanelComponent },
    { id: "settings", label: "Settings", component: SettingsPanelComponent },
  ];
  readonly query = signal(currentQuery());
  readonly alive = signal(true);
  readonly readQuery = currentQuery;

  // Like a page reload for the tabs: destroy
  // them, then create them again from the URL.
  remount() {
    this.alive.set(false);
    setTimeout(() => this.alive.set(true));
  }

  back() {
    window.history.back();
  }
  forward() {
    window.history.forward();
  }

  @HostListener("window:popstate")
  onPop() {
    this.query.set(currentQuery());
  }
}
